import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.DYAmjhAm.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Breeze","text":"Data management for JavaScript clients","tagline":"Query, cache, track changes and save entity graphs — against any service that speaks HTTP and JSON.","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Migrating from 2.x","link":"/guide/migrating-from-2x"},{"theme":"alt","text":"API reference","link":"/api/"}]},"features":[{"title":"Rich queries, client-side","details":"Compose queries with a fluent API and real predicates, run them against the server or against the cache with the same syntax.","link":"/query/"},{"title":"Change tracking that knows your model","details":"Entities track their own state and original values. Save a whole graph in one transaction, and validate before you send it.","link":"/guide/change-tracking"},{"title":"Metadata-driven","details":"Breeze learns your model from server metadata — types, keys, relationships — so navigation properties and fixups just work.","link":"/metadata/"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1789151433000}'),r={name:"index.md"};function o(s,e,d,l,c,g){return a(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="breeze-3" tabindex="-1">Breeze 3 <a class="header-anchor" href="#breeze-3" aria-label="Permalink to &quot;Breeze 3&quot;">​</a></h2><p>Version 3 is a rewrite of the 2.x codebase with the same public API. What changed:</p><ul><li><strong>ESM only</strong>, one package, one npm tag. No CommonJS build, no UMD bundle, no <code>mjs</code>/<code>cjs</code> dist-tags to choose between.</li><li><strong>No runtime dependencies.</strong></li><li><strong>No adapter setup</strong> — Breeze uses its standard adapters unless you register others. When you do, <a href="/breeze-client-v3/guide/configuration"><code>configureBreeze</code></a> replaces the stringly-typed adapter registration.</li><li><strong>Knockout, jQuery, AngularJS and OData support removed.</strong> See <a href="/breeze-client-v3/guide/migrating-from-2x">Migrating from 2.x</a> for what to do if you use them.</li><li>Built under <code>strictNullChecks</code> and <code>noImplicitAny</code>.</li></ul><p>If you are coming from 2.x, start with <a href="/breeze-client-v3/guide/migrating-from-2x">Migrating from 2.x</a> — most applications need only a handful of changes, and they are listed there.</p><div class="warning custom-block"><p class="custom-block-title">Not yet released</p><p>Breeze 3 is in development. The API is stable in shape but not yet published to npm.</p></div>',5)])])}const p=t(r,[["render",o]]);export{h as __pageData,p as default};
